//! The vendored pure-Rust Silero must match the OFFICIAL model run the official
//! way (snakers4/silero-vad `OnnxWrapper`: 64-sample context, state carry)
//! through onnxruntime, chunk by chunk.
//!
//! Reference: `testdata/fixtures/silero_v6.2.3_ctx_aepyx_16k.json`, generated by
//! `scripts/gen-golden-official.py`. Audio: `scripts/fetch-golden.sh`. CI sets
//! `REQUIRE_GOLDEN=1` so missing audio fails instead of skipping.
//!
//! History: upstream's own golden data ran onnxruntime on bare 512-sample
//! chunks without the context, so port and reference agreed while both scored
//! real speech below 0.11. This test guards against that class of mistake by
//! also requiring that the speech file actually scores as speech.

use std::path::PathBuf;

use recorder_vad::{EngineKind, new_engine};

fn repo() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

/// Pulls `"probs": [...]` out of the reference JSON without a JSON dependency.
fn reference_probs(json: &str) -> Vec<f32> {
    let start = json.find("\"probs\"").expect("probs key") + "\"probs\"".len();
    let open = start + json[start..].find('[').expect("probs array");
    let close = open + json[open..].find(']').expect("probs array end");
    json[open + 1..close].split(',').map(|v| v.trim().parse::<f32>().expect("number")).collect()
}

#[test]
fn silero_matches_official_onnxruntime_on_real_speech() {
    let wav = repo().join("testdata/golden/aepyx.wav");
    if !wav.exists() {
        assert!(
            std::env::var_os("REQUIRE_GOLDEN").is_none(),
            "golden audio missing: run scripts/fetch-golden.sh"
        );
        eprintln!("skipping: golden audio missing (run scripts/fetch-golden.sh)");
        return;
    }
    let fixture = repo().join("testdata/fixtures/silero_v6.2.3_ctx_aepyx_16k.json");
    let expected = reference_probs(&std::fs::read_to_string(fixture).unwrap());
    let (sample_rate, samples) = silero_vad_pure::read_wav(&wav).expect("read wav");
    assert_eq!(sample_rate, 16_000);

    let mut vad = new_engine(EngineKind::Silero).unwrap();
    let got: Vec<f32> =
        samples.chunks_exact(vad.frame_len()).map(|chunk| vad.process(chunk).unwrap()).collect();
    assert_eq!(got.len(), expected.len(), "chunk count");

    let max_err = got.iter().zip(&expected).map(|(g, e)| (g - e).abs()).fold(0.0f32, f32::max);
    assert!(max_err < 1e-4, "max |rust - onnxruntime| = {max_err}");

    // Decisions at the 0.5 threshold must agree exactly (that is what the controller sees).
    let flips = got.iter().zip(&expected).filter(|(g, e)| (**g >= 0.5) != (**e >= 0.5)).count();
    assert_eq!(flips, 0, "speech/non-speech decisions differ from onnxruntime");

    // Sanity: this is a speech recording, so most chunks must score as speech.
    let speech = got.iter().filter(|p| **p >= 0.5).count() as f32 / got.len() as f32;
    assert!(speech > 0.6, "only {:.0}% of a speech file scored as speech", speech * 100.0);
    eprintln!(
        "silero vs official onnxruntime: {} chunks, max abs error {max_err:e}, {:.0}% speech",
        got.len(),
        speech * 100.0
    );
}
